const byKey = new Map(BRANDS.map((brand) => [brand.key, brand]));

export const findBrand = (key: string) => byKey.get(key);

const normalise = (text: string) => text.toLowerCase().replace(/[^a-z0-9+]+/g, ' ').trim();
const termsOf = (brand: BrandPreset) => [brand.name, ...brand.keywords].map(normalise);

export function searchBrands(query: string): BrandPreset[] {
  const wanted = normalise(query);
  if (!wanted) return BRANDS;
  return BRANDS.filter((brand) => termsOf(brand).some((term) => term.includes(wanted)));
}

// The preset an account or schedule name clearly refers to, like 'Netflix Premium' or 'GCash wallet'.
export function brandForName(name: string): BrandPreset | undefined {
  const words = ` ${normalise(name)} `;
  if (words.trim().length < 2) return undefined;
  return BRANDS.find((brand) => termsOf(brand).some((term) => term.length > 1 && words.includes(` ${term} `)));
}
